function validate(input) {
  const [{ Scores = [] }] = input;
  const seen = new Set();
  for (const [, gender, day, points] of Scores) {
    if (gender !== 'F' && gender !== 'M') return "gender must be 'F' or 'M'.";
    if (day === null) return 'Every row needs a day.';
    if (points === null) return 'score_points is never null.';
    const key = `${gender}/${day}`;
    if (seen.has(key)) return `Gender ${gender} has two rows on ${day}.`;
    seen.add(key);
  }
  return null;
}

