function generate(rand, size) {
  const names = ['Aron', 'Alice', 'Bajrang', 'Khali', 'Slaman', 'Joe', 'Jose', 'Priya'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const dayText = offset => new Date(Date.UTC(2019, 11, 1) + offset * 86400000).toISOString().slice(0, 10);
  const rows = [];
  for (const gender of ['F', 'M']) {
    if (size === 'small') {
      // Few days near the turn of the year, shared between the genders so their days interleave.
      const days = [17, 24, 29, 30, 31, 37].filter(() => rand() < 0.4);
      for (const d of days) rows.push([pick(names), gender, dayText(d), Math.floor(rand() * 25)]);
    } else {
      let d = 0;
      for (let i = 0; i < 1000; i++) {
        d += 1 + Math.floor(rand() * 3);
        rows.push([`${pick(names)}${Math.floor(rand() * 50)}`, gender, dayText(d), Math.floor(rand() * 100)]);
      }
    }
  }
  // Shuffle so the input order says nothing about the answer's order.
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [{ Scores: rows }];
}
